import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.reflect.Field;

public class Main {
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.FIELD)
    @interface 记录 {
        String value();
        int 根数() default 1;
    }

    static class 小猫 {
        @记录(value = "{a1}", 根数 = 3)
        String {f1} = "小橘";

        @记录(value = "存粮")
        int {f2} = 5;

        int {f3} = 4;
    }

    public static void main(String[] args) throws Exception {
        for (String 骨头名 : new String[]{"{f1}", "{f2}", "{f3}"}) {
            Field 骨头 = 小猫.class.getDeclaredField(骨头名);
            记录 小纸条 = 骨头.getAnnotation(记录.class);
            if (小纸条 == null) {
                System.out.println(骨头名 + "：没贴纸条");
            } else {
                System.out.println(骨头名 + "：" + 小纸条.value() + " " + 小纸条.根数() + " 根");
            }
        }
    }
}
